# --- 1. HIDE CONSOLE WINDOW ---
Add-Type -Name Window -Namespace Console -MemberDefinition '
[DllImport("Kernel32.dll")]
public static extern IntPtr GetConsoleWindow();
[DllImport("user32.dll")]
public static extern bool ShowWindow(IntPtr hWnd, Int32 nCmdShow);
'
$consolePtr = [Console.Window]::GetConsoleWindow()
[Console.Window]::ShowWindow($consolePtr, 0)

# --- 2. SHELL REFRESH API ---
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class ShellIconRefresh {
    [DllImport("shell32.dll")]
    public static extern void SHChangeNotify(uint wEventId, uint uFlags, IntPtr dwItem1, IntPtr dwItem2);
}
"@

# --- 3. RELATIVE PATH CALCULATOR ---
function Get-RelativePath {
    param ([string]$fromPath, [string]$toPath)
    
    $fromPath = $fromPath.TrimEnd('\')
    $toPath = $toPath.TrimEnd('\')
    
    $fromParts = $fromPath.Split('\')
    $toParts = $toPath.Split('\')
    
    $commonLength = 0
    $minLength = [Math]::Min($fromParts.Length, $toParts.Length)
    
    for ($i = 0; $i -lt $minLength; $i++) {
        if ($fromParts[$i] -eq $toParts[$i]) {
            $commonLength = $i + 1
        } else {
            break
        }
    }
    
    if ($commonLength -eq 0) { return $toPath }
    
    $ups = $fromParts.Length - $commonLength
    $relative = ""
    
    for ($i = 0; $i -lt $ups; $i++) { $relative += "..\" }
    for ($i = $commonLength; $i -lt $toParts.Length; $i++) { $relative += $toParts[$i] + "\" }
    
    return $relative.TrimEnd('\')
}

# --- NEW: READ EXISTING ICON ---
function Get-ExistingIcon {
    param ([string]$targetFolder)
    
    if (-not $targetFolder -or -not (Test-Path $targetFolder -PathType Container)) { return }
    
    $iniPath = Join-Path $targetFolder "desktop.ini"
    
    if (Test-Path $iniPath) {
        try {
            $content = Get-Content $iniPath -Raw
            # Look for IconResource=...
            if ($content -match 'IconResource=(.+)') {
                $iconPath = $Matches[1].Trim()
                
                # Remove trailing index if present (e.g., ",0")
                $iconPath = $iconPath -replace ',\d+$', ''
                
                # If it's a relative path, convert it to absolute for the text box
                if (-not [System.IO.Path]::IsPathRooted($iconPath)) {
                    $iconPath = [System.IO.Path]::GetFullPath([System.IO.Path]::Combine($targetFolder, $iconPath))
                }
                
                $txtIcon.Text = $iconPath
                return
            }
        } catch {
            # Ignore read errors
        }
    }
    # If no ini or no icon found, clear the box
    $txtIcon.Text = ""
}

# --- 4. LOAD GUI LIBRARIES ---
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$form = New-Object System.Windows.Forms.Form
$form.Text = "Set Folder Icon"
$form.Size = New-Object System.Drawing.Size(460, 260)
$form.StartPosition = "CenterScreen"
$form.FormBorderStyle = "FixedDialog"
$form.MaximizeBox = $false

# --- Folder row ---
$lblF = New-Object System.Windows.Forms.Label
$lblF.Text = "Target folder (drop or browse):"
$lblF.Location = New-Object System.Drawing.Point(10, 15); $lblF.AutoSize = $true
$form.Controls.Add($lblF)

$txtFolder = New-Object System.Windows.Forms.TextBox
$txtFolder.Location = New-Object System.Drawing.Point(10, 35)
$txtFolder.Size = New-Object System.Drawing.Size(340, 20)
$txtFolder.AllowDrop = $true
$form.Controls.Add($txtFolder)

$btnBF = New-Object System.Windows.Forms.Button
$btnBF.Text = "..."; $btnBF.Location = New-Object System.Drawing.Point(360, 34)
$btnBF.Size = New-Object System.Drawing.Size(60, 23)
$form.Controls.Add($btnBF)

# --- Icon row ---
$lblI = New-Object System.Windows.Forms.Label
$lblI.Text = "Icon file (drop or browse):"
$lblI.Location = New-Object System.Drawing.Point(10, 70); $lblI.AutoSize = $true
$form.Controls.Add($lblI)

$txtIcon = New-Object System.Windows.Forms.TextBox
$txtIcon.Location = New-Object System.Drawing.Point(10, 90)
$txtIcon.Size = New-Object System.Drawing.Size(340, 20)
$txtIcon.AllowDrop = $true
$form.Controls.Add($txtIcon)

$btnBI = New-Object System.Windows.Forms.Button
$btnBI.Text = "..."; $btnBI.Location = New-Object System.Drawing.Point(360, 89)
$btnBI.Size = New-Object System.Drawing.Size(60, 23)
$form.Controls.Add($btnBI)

# --- Set button ---
$btnSet = New-Object System.Windows.Forms.Button
$btnSet.Text = "Set"
$btnSet.Location = New-Object System.Drawing.Point(180, 135)
$btnSet.Size = New-Object System.Drawing.Size(100, 30)
$form.Controls.Add($btnSet)

# --- Status ---
$lblStatus = New-Object System.Windows.Forms.Label
$lblStatus.Text = ""
$lblStatus.Location = New-Object System.Drawing.Point(10, 180)
$lblStatus.Size = New-Object System.Drawing.Size(430, 40)
$lblStatus.ForeColor = "DarkGreen"
$form.Controls.Add($lblStatus)

# --- Drag & Drop handlers ---
$txtFolder.Add_DragEnter({ if ($_.Data.GetDataPresent("FileDrop")) { $_.Effect = "Copy" } })
$txtFolder.Add_DragDrop({
    $f = $_.Data.GetData("FileDrop")
    if ($f -and (Test-Path $f[0] -PathType Container)) { 
        $this.Text = $f[0] 
        Get-ExistingIcon -targetFolder $f[0] # <-- NEW: Check for existing icon
    }
})

$txtIcon.Add_DragEnter({ if ($_.Data.GetDataPresent("FileDrop")) { $_.Effect = "Copy" } })
$txtIcon.Add_DragDrop({
    $f = $_.Data.GetData("FileDrop")
    if ($f -and (Test-Path $f[0] -PathType Leaf)) { $this.Text = $f[0] }
})

# --- Browse buttons ---
$btnBF.Add_Click({
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    $d.Description = "Select target folder"
    if ($d.ShowDialog() -eq "OK") { 
        $txtFolder.Text = $d.SelectedPath 
        Get-ExistingIcon -targetFolder $d.SelectedPath # <-- NEW: Check for existing icon
    }
})
$btnBI.Add_Click({
    $d = New-Object System.Windows.Forms.OpenFileDialog
    $d.Filter = "Icons (*.ico)|*.ico|All files (*.*)|*.*"
    $d.Title = "Select icon file"
    if ($d.ShowDialog() -eq "OK") { $txtIcon.Text = $d.FileName }
})

# --- Set button logic ---
$btnSet.Add_Click({
    $folder = $txtFolder.Text.Trim()
    $icon   = $txtIcon.Text.Trim()

    if (-not $folder -or -not (Test-Path $folder -PathType Container)) {
        [System.Windows.Forms.MessageBox]::Show("Select a valid folder.","Error","OK","Error"); return
    }
    if (-not $icon -or -not (Test-Path $icon -PathType Leaf)) {
        [System.Windows.Forms.MessageBox]::Show("Select a valid icon file.","Error","OK","Error"); return
    }

    $iconResourcePath = Get-RelativePath -fromPath $folder -toPath $icon
    $iniPath  = Join-Path $folder "desktop.ini"
    $content  = "[.ShellClassInfo]`r`nIconResource=$iconResourcePath`r`n"

    try {
        if (Test-Path $iniPath) {
            $existingFile = Get-Item $iniPath -Force
            $existingFile.Attributes = [System.IO.FileAttributes]::Normal
        }

        [System.IO.File]::WriteAllText($iniPath, $content, [System.Text.Encoding]::Unicode)

        $ini = Get-Item $iniPath -Force
        $ini.Attributes = [System.IO.FileAttributes]::Hidden -bor [System.IO.FileAttributes]::System

        $fld = Get-Item $folder -Force
        $fld.Attributes = $fld.Attributes -bor [System.IO.FileAttributes]::System

        # Force Icon Refresh
        $folderPtr = [System.Runtime.InteropServices.Marshal]::StringToHGlobalUni($folder)
        [ShellIconRefresh]::SHChangeNotify(0x00002000, 0x0001, $folderPtr, [IntPtr]::Zero)
        Start-Sleep -Milliseconds 100
        [ShellIconRefresh]::SHChangeNotify(0x08000000, 0x0000, [IntPtr]::Zero, [IntPtr]::Zero)
        [System.Runtime.InteropServices.Marshal]::FreeHGlobal($folderPtr)

        $lblStatus.ForeColor = "DarkGreen"
        $lblStatus.Text = "Success! Icon applied and cache refreshed."
    } catch {
        $lblStatus.ForeColor = "DarkRed"
        $lblStatus.Text = "Error: $_"
    }
})

[void]$form.ShowDialog()
